static void intToIp(uint64_t v,char* out){sprintf(out,"%u.%u.%u.%u",(unsigned)((v>>24)&255),(unsigned)((v>>16)&255),(unsigned)((v>>8)&255),(unsigned)(v&255));}
char** ipToCIDR(char* ip,int n,int* returnSize){
    int cap=32,sz=0; char** out=(char**)malloc(cap*sizeof(char*)); uint64_t start=ipToInt(ip);
    while(n>0){
      uint64_t align=start==0?(1ULL<<32):(start&(~start+1)); uint64_t size=1; while(size*2<=(unsigned)n) size*=2; uint64_t block=align<size?align:size;
      int bits=0; for(uint64_t t=block;t>1;t/=2) bits++; if(sz==cap){cap*=2;out=(char**)realloc(out,cap*sizeof(char*));}
      out[sz]=(char*)malloc(32); char buf[32]; intToIp(start,buf); sprintf(out[sz],"%s/%d",buf,32-bits); sz++; start+=block; n-=(int)block;
