class Solution {
    public List<String> ipToCIDR(String ip, int n) {
        long start=0; for(String p:ip.split("\\.")) start=start*256+Integer.parseInt(p);
        List<String> out=new ArrayList<>();
        while(n>0){
            long align = start==0 ? (1L<<32) : (start & -start);
            long size=1; while(size*2<=n) size*=2;
            long block=Math.min(align,size);
            int bits=0; for(long t=block;t>1;t/=2) bits++;
            out.add(toIp(start)+"/"+(32-bits));
            start+=block; n-=(int)block;
        }
        return out;
    }
    private String toIp(long v){ return ((v>>24)&255)+"."+((v>>16)&255)+"."+((v>>8)&255)+"."+(v&255); }
}

