import sys, json
class Solution:
    def ipToCIDR(self, ip, n):
        def ip_to_int(s):
            v=0
            for part in s.split("."):
                v=v*256+int(part)
            return v
        def int_to_ip(v):
            return ".".join(str((v >> sh) & 255) for sh in (24,16,8,0))
        start=ip_to_int(ip)
        ans=[]
        while n:
            align=(1<<32) if start==0 else (start & -start)
            size=1 << (n.bit_length()-1)
            block=min(align,size)
            prefix=32-int(math.log2(block))
            ans.append(int_to_ip(start)+"/"+str(prefix))
            start += block; n -= block
        return ans

