function ipToCIDR(ip,n){
  const parts=ip.split('.').map(Number);
  let start=parts[0]*256*256*256+parts[1]*256*256+parts[2]*256+parts[3];
  const toIp=v=>[Math.floor(v/16777216)%256,Math.floor(v/65536)%256,Math.floor(v/256)%256,v%256].join('.');
  const highestPow2=x=>{let p=1;while(p*2<=x)p*=2;return p;};
  const out=[];
  while(n>0){
    let align=1;
    if(start!==0){while(start%(align*2)===0)align*=2;} else align=4294967296;
    const block=Math.min(align,highestPow2(n));
    let bits=0,t=block; while(t>1){t/=2;bits++;}
    out.push(toIp(start)+'/'+(32-bits));
    start+=block; n-=block;
  }
  return out;
}

